  const desktopPluginPanel = createDesktopPluginPanel(ctx)
  ctx.effect(() => () => desktopPluginPanel.dispose?.(), 'dsh-skin-market: native install tracking')
  ctx.slots.inject('settings.section', () => ctx.slots.register({
