  const home = resolve(options.home)
  const file = join(home, 'cordis.patch.yml')
  if (options.patchPath !== undefined && resolve(options.patchPath) === file) return { status: 'blocked', reason: '宿主的共享配置与当前配置位置重合，无法确认配置层级。' }
