      "path": "src/client/index.ts",
      "content": "import { createElement as h } from 'react'\nimport * as primitives from '@deepseek-ai/dsh-client-ui-primitives'\nimport { SkinMarketSection } from './SkinMarketSection.tsx'\nimport { createDesktopPluginPanel } from './desktop-plugin-panel.ts'\nimport { createTranslator, hostDictionaries, type MessageKey, type Translator } from './i18n.ts'\n\nconst namespace = 'dsh-skin-market'\n\ninterface ClientContext {\n  get?: (name: string) => unknown\n  on?: (event: 'internal/status', listener: () => void) => () => void\n  effect(callback: () => unknown, label?: string): void\n  locale: {\n    register(namespace: string, dictionaries: Record<string, Record<string, string>>): unknown\n    bind(namespace: string): (key: string) => string\n    getSnapshot?: () => { active?: string }\n  }\n  loader: ClientLoader\n  slots: { inject(slot: string, callback: () => unknown): void; register(meta: Record<string, unknown>, component: () => unknown): unknown; entriesOfSlot?: (slot: string) => readonly unknown[] }\n  layout?: { selectPanel(panelId: string): void }\n}\n\ninterface ClientLoaderEntry {\n  options: { name: string; disabled?: boolean | null }\n  disabled?: boolean | null\n  fiber?: { state?: number }\n  update(options: { disabled: boolean | null }, create?: boolean, force?: boolean): Promise<void>\n}\n\ninterface ClientLoader { entries(): Iterable<ClientLoaderEntry> }\n\nexport interface ClientSkinRuntime {\n  /** Returns whether the loader accepted the request; probeActive confirms its outcome. */\n  setActive(packageName: string, active: boolean): Promise<boolean>\n  probeActive?(packageName: string): ClientSkinActivity\n  /** False only after the browser module graph has finished unloading old entries. */\n  probeSyncing?(): boolean | undefined\n  observe?(listener: () => void): () => void\n}\n\nexport type ClientSkinActivity = 'active' | 'loading' | 'pending' | 'failed' | 'missing' | 'disabled' | 'unknown'\n\nexport interface ClientSkinExpectation { package: string; active: boolean }\n\nexport interface ClientSkinSelectionStatus {\n  status: 'applied' | 'switching' | 'restart-required' | 'unavailable'\n  package?: string\n  activity?: ClientSkinActivity\n}\n\n/** Check the whole browser selection, including preserved plugins and retired skins. */\nexport function probeClientSkinSelection(runtime: ClientSkinRuntime, expected: readonly ClientSkinExpectation[]): ClientSkinSelectionStatus {\n  const targets = new Map<string, boolean>()\n  for (const target of expected) {\n    if (targets.has(target.package) && targets.get(target.package) !== target.active) return { status: 'unavailable', package: target.package, activity: 'unknown' }\n    targets.set(target.package, target.active)\n  }\n  let syncing: boolean | undefined\n  try { syncing = runtime.probeSyncing?.() } catch { /* An older host cannot confirm graph settlement. */ }\n  if (syncing === true) return { status: 'switching', activity: 'loading' }\n  const unresolved = [...targets].flatMap(([packageName, active]) => {\n    let activity: ClientSkinActivity\n    try { activity = runtime.probeActive?.(packageName) ?? 'unknown' } catch { activity = 'unknown' }\n    if (active ? activity === 'active' : activity === 'disabled' || activity === 'missing') {\n      // Entries leave the roster before their fibers finish disposing. Only\n      // the graph's settled snapshot confirms that an absent old skin is gone.\n      if (!active && syncing !== false) return [{ package: packageName, activity: 'unknown' as const }]\n      return []\n    }\n    return [{ package: packageName, activity }]\n  })\n  const unavailable = unresolved.find(item => item.activity === 'failed' || item.activity === 'unknown')\n  if (unavailable !== undefined) return { status: 'unavailable', ...unavailable }\n  const switching = unresolved.find(item => item.activity === 'loading' || item.activity === 'pending')\n  if (switching !== undefined) return { status: 'switching', ...switching }\n  const pending = unresolved[0]\n  return pending === undefined ? { status: 'applied' } : { status: 'restart-required', ...pending }\n}\n\nexport async function switchClientSkin(runtime: ClientSkinRuntime, packageNames: string[], target: string, preserved: Iterable<string> = []): Promise<boolean> {\n  const keep = new Set([...preserved, target])\n  for (const packageName of packageNames) {\n    if (!keep.has(packageName)) await runtime.setActive(packageName, false)\n  }\n  return runtime.setActive(target, true)\n}\n\ninterface ClientModuleSnapshot { syncing?: boolean }\ninterface ClientModuleStore {\n  getSnapshot?(): ClientModuleSnapshot\n  subscribe?(listener: () => void): () => void\n}\n\nexport function createClientSkinRuntime(loader: ClientLoader, events?: Pick<ClientContext, 'on' | 'get'>): ClientSkinRuntime {\n  const moduleStore = (): ClientModuleStore | undefined => {\n    try { return (events?.get?.('modules') as { entries?: { state?: ClientModuleStore } } | undefined)?.entries?.state } catch { return undefined }\n  }\n  return {\n    probeSyncing() {\n      try {\n        const syncing = moduleStore()?.getSnapshot?.().syncing\n        return typeof syncing === 'boolean' ? syncing : undefined\n      } catch { return undefined }\n    },\n    observe(listener) {\n      let active = true\n      const disposers: Array<() => void> = []\n      const notify = () => {\n        if (!active) return\n        try { listener() } catch { /* A stale view must not break a fiber transition. */ }\n      }\n      try {\n        // Cordis owns this listener with the market plugin's context; the view\n        // also releases it on unmount. No loader entry is changed here.\n        const dispose = events?.on?.('internal/status', notify)\n        if (typeof dispose === 'function') disposers.push(dispose)\n      } catch { /* Some old contexts cannot observe fiber status. */ }\n      try {\n        const dispose = moduleStore()?.subscribe?.(notify)\n        if (typeof dispose === 'function') disposers.push(dispose)\n      } catch { /* The fiber observer still works without the module store. */ }\n      return () => {\n        if (!active) return\n        active = false\n        for (const dispose of disposers) dispose()\n      }\n    },\n    probeActive(packageName) {\n      try {\n        // The browser module graph emits its package name as manifest row id;\n        // this differs from the host's cordis.patch.yml plugin row id.\n        const matches = [...loader.entries()].filter(item => item.options.name === packageName)\n        if (matches.length === 0) return 'missing'\n        if (matches.length !== 1) return 'unknown'\n        const entry = matches[0]!\n        if (entry.fiber?.state === 5) return 'loading'\n        if (entry.disabled === true || entry.options.disabled === true) {\n          if (entry.fiber?.state === 0) return 'pending'\n          if (entry.fiber?.state === 1 || entry.fiber?.state === 2) return 'loading'\n          if (entry.fiber?.state === 3) return 'failed'\n          return entry.fiber?.state === undefined || entry.fiber.state === 4 ? 'disabled' : 'unknown'\n        }\n        // Mirror the pinned Cordis const enum, which has no runtime object.\n        switch (entry.fiber?.state) {\n          case 0: return 'pending'\n          case 1: return 'loading'\n          case 2: return 'active'\n          case 3: return 'failed'\n          default: return 'unknown'\n        }\n      } catch { return 'unknown' }\n    },\n    async setActive(packageName, active) {\n      const entry = [...loader.entries()].find(item => item.options.name === packageName)\n      if (entry === undefined) return false\n      await entry.update({ disabled: active ? null : true }, false, true)\n      return true\n    },\n  }\n}\n\nexport const name = 'dsh-skin-market'\nexport const inject = ['slots', 'locale', 'loader']\nexport const REQUIRED_PRIMITIVES = ['Button', 'Input', 'Modal', 'Pill', 'Switch'] as const\n\nexport function missingPrimitives(module: Record<string, unknown>): string[] {\n  return REQUIRED_PRIMITIVES.filter(key => module[key] === undefined)\n}\n\nexport function apply(ctx: ClientContext): void {\n  const missing = missingPrimitives(primitives as unknown as Record<string, unknown>)\n  if (missing.length > 0) {\n    console.warn(`[dsh-skin-market] missing DSH primitives: ${missing.join(', ')}`)\n    return\n  }\n  ctx.effect(() => ctx.locale.register(namespace, hostDictionaries), 'dsh-skin-market: locale')\n  const hostLocale = () => {\n    try {\n      const active = ctx.locale.getSnapshot?.().active?.toLowerCase()\n      return active?.startsWith('en') === true ? 'en' : 'zh'\n    } catch {\n      return 'zh'\n    }\n  }\n  const t: Translator = createTranslator(ctx.locale.bind(namespace), 'zh', hostLocale)\n  const hostT = (key: string): string => t(key as MessageKey)\n  const clientRuntime = createClientSkinRuntime(ctx.loader, ctx)\n  const desktopPluginPanel = createDesktopPluginPanel(ctx)\n  ctx.effect(() => () => desktopPluginPanel.dispose?.(), 'dsh-skin-market: native install tracking')\n  ctx.slots.inject('settings.section', () => ctx.slots.register({\n    name: 'settings.section', id: 'skin-market', order: 45, label: () => t('nav.market'), locale: namespace, inject: () => ({ t: hostT }),\n  }, () => h(SkinMarketSection, { t, clientRuntime, desktopPluginPanel, layout: 'fill' })))\n  // The injection stays dormant on older hosts and registers when the new\n  // Plugins page owns this slot. Both entry points use the same market UI.\n  ctx.slots.inject('plugins.bundle.config', () => ctx.slots.register({\n    name: 'plugins.bundle.config', key: namespace, locale: namespace, inject: () => ({ t: hostT }),\n  }, () => h(SkinMarketSection, { t, clientRuntime, desktopPluginPanel, layout: 'embedded' })))\n}\n\nexport { SkinMarketSection } from './SkinMarketSection.tsx'\n"
    },
    {
      "path": "src/catalog.ts",
      "content": "import { existsSync, readFileSync } from 'node:fs'\nimport { join } from 'node:path'\nimport Ajv from 'ajv/dist/2020.js'\nimport { decodeCatalogWire, encodeCatalogWire } from './catalog-wire.ts'\nimport { githubInstallTarget, parseGithubTarget } from './install-resolution.ts'\nimport { localizedSkinNameRecord } from './localized-copy.ts'\nimport { atomicWriteJson } from './profile.ts'\nimport { isVersionRange } from './semver.ts'\nimport type { CatalogFile, CatalogSkin, SkinEntry } from './types.ts'\n\nexport const REMOTE_CATALOG_URL = 'https://raw.githubusercontent.com/kingOfSoySauce/dsh-skin-market/main/data/catalog.json'\nexport const CATALOG_REFRESH_INTERVAL_MS = 5 * 60 * 1000\nexport const LOCAL_CATALOG_ENV = 'DSH_SKIN_MARKET_LOCAL_CATALOG'\n\nconst schema = JSON.parse(readFileSync(new URL('../registry/skin.schema.json', import.meta.url), 'utf8')) as object\nconst validateSkin = new Ajv({ allErrors: true, strict: false, validateFormats: false }).compile(schema)\n\nexport function loadCatalog(): CatalogFile {\n  const file = new URL('../data/catalog.json', import.meta.url)\n  return validateCatalog(JSON.parse(readFileSync(file, 'utf8')))\n}\n\nexport function validateCatalog(value: unknown): CatalogFile {\n  const candidate = decodeCatalogWire(value)\n\n  const ids = new Set<string>()\n  const packages = new Set<string>()\n  const rows = new Set<string>()\n  for (const skin of candidate.skins) {\n    if (!validateSkin(skin)) {\n      const details = (validateSkin.errors ?? []).map(error => `${error.instancePath || '/'} ${error.message}`).join('; ')\n      throw new Error(`invalid skin entry: ${details}`)\n    }\n    const entry = skin as SkinEntry\n    if (entry.install.desktop?.mode === 'managed') {\n      if (entry.install.desktop.packageName !== entry.package) {\n        throw new Error(`invalid Desktop package name for ${entry.id}: expected ${entry.package}`)\n      }\n      if (entry.install.desktop.packageVersion !== entry.install.version) {\n        throw new Error(`invalid Desktop package version for ${entry.id}: expected ${entry.install.version}`)\n      }\n    }\n    if (!isVersionRange(entry.compatibility.dsh)) throw new Error(`invalid DSH compatibility range for ${entry.id}`)\n    for (const adapter of entry.compatibility.adapters ?? []) {\n      if (!isVersionRange(adapter.when)) throw new Error(`invalid compatibility adapter range for ${entry.id}: ${adapter.id}`)\n    }\n    const repo = entry.repo.replace(/^https:\\/\\/github\\.com\\//, '').replace(/\\/$/, '')\n    const expected = githubInstallTarget(repo, entry.install.commit, entry.subpath)\n    if (entry.install.target !== expected) throw new Error(`invalid pinned install target for ${entry.id}`)\n    for (const companion of entry.install.companions ?? []) {\n      const parts = parseGithubTarget(companion.target)\n      if (parts === null) throw new Error(`invalid companion target for ${entry.id}: ${companion.package}`)\n      if (parts.commit !== companion.commit) throw new Error(`invalid companion commit for ${entry.id}: ${companion.package}`)\n      if (companion.target !== githubInstallTarget(parts.repository, companion.commit, parts.subpath)) {\n        throw new Error(`invalid companion path for ${entry.id}: ${companion.package}`)\n      }\n    }\n    if ((entry.install.companions?.length ?? 0) > 0 && entry.install.desktop?.mode === 'managed') {\n      throw new Error(`desktop managed install cannot install companions for ${entry.id}`)\n    }\n    if (entry.subpath !== undefined && entry.install.allowBuild !== undefined && !entry.install.allowBuild.endsWith(`#path:${entry.subpath}`)) {\n      throw new Error(`invalid allowBuild path for ${entry.id}; expected #path:${entry.subpath}`)\n    }\n    if (ids.has(entry.id)) throw new Error(`duplicate id: ${entry.id}`)\n    ids.add(entry.id)\n    // Forks can publish the same package name or loader id. Install matching\n    // still requires this entry's pinned commit, so the catalog can list both.\n    const packageKey = `${entry.package}\\n${entry.repo}`\n    if (packages.has(packageKey)) throw new Error(`duplicate package: ${entry.package} in ${entry.repo}`)\n    packages.add(packageKey)\n    const rowKey = `${entry.rowId}\\n${entry.package}\\n${entry.repo}`\n    if (rows.has(rowKey)) throw new Error(`duplicate rowId: ${entry.rowId} for ${entry.package}`)\n    rows.add(rowKey)\n  }\n  return candidate as CatalogFile\n}\n\nexport type CatalogSource = 'remote' | 'cache' | 'bundled'\n\nexport interface CatalogSnapshot {\n  catalog: CatalogFile\n  source: CatalogSource\n  lastCheckedAt: string | null\n  error?: string\n}\n\ninterface FetchResponse {\n  ok: boolean\n  status: number\n  json(): Promise<unknown>\n}\n\nexport interface CatalogStoreOptions {\n  remoteUrl?: string\n  /** Keep the bundled registry for local plugin development; never call the remote catalog. */\n  preferBundled?: boolean\n  refreshIntervalMs?: number\n  fetcher?: (url: string, init: RequestInit) => Promise<FetchResponse>\n  now?: () => number\n}\n\nfunction cacheFile(profileDir: string): string { return join(profileDir, '.dsh-skin-market', 'catalog.json') }\nfunction errorMessage(error: unknown): string { return error instanceof Error ? error.message : String(error) }\n\nexport class CatalogStore {\n  private current: CatalogFile\n  private source: CatalogSource = 'bundled'\n  private checkedAt = 0\n  private error?: string\n  private refreshing?: Promise<CatalogSnapshot>\n  private readonly remoteUrl: string\n  private readonly preferBundled: boolean\n  private readonly refreshIntervalMs: number\n  private readonly fetcher: (url: string, init: RequestInit) => Promise<FetchResponse>\n  private readonly now: () => number\n\n  constructor(private readonly profileDir: string, options: CatalogStoreOptions = {}) {\n    const bundled = loadCatalog()\n    this.current = bundled\n    this.remoteUrl = options.remoteUrl ?? REMOTE_CATALOG_URL\n    this.preferBundled = options.preferBundled ?? process.env[LOCAL_CATALOG_ENV] === '1'\n    this.refreshIntervalMs = options.refreshIntervalMs ?? CATALOG_REFRESH_INTERVAL_MS\n    this.fetcher = options.fetcher ?? ((url, init) => fetch(url, init))\n    this.now = options.now ?? Date.now\n\n    const file = cacheFile(profileDir)\n    if (!this.preferBundled && existsSync(file)) {\n      try {\n        const cached = validateCatalog(JSON.parse(readFileSync(file, 'utf8')))\n        if (Date.parse(cached.generatedAt) >= Date.parse(bundled.generatedAt)) {\n          this.current = cached\n          this.source = 'cache'\n        }\n      } catch (error) {\n        this.error = `cached catalog rejected: ${errorMessage(error)}`\n      }\n    }\n  }\n\n  snapshot(): CatalogSnapshot {\n    return {\n      catalog: this.current,\n      source: this.source,\n      lastCheckedAt: this.checkedAt === 0 ? null : new Date(this.checkedAt).toISOString(),\n      ...(this.error ? { error: this.error } : {}),\n    }\n  }\n\n  async refresh(force = false): Promise<CatalogSnapshot> {\n    if (this.preferBundled) return this.snapshot()\n    if (!force && this.checkedAt !== 0 && this.now() - this.checkedAt < this.refreshIntervalMs) return this.snapshot()\n    if (this.refreshing !== undefined) return this.refreshing\n    this.refreshing = this.fetchRemote()\n    try { return await this.refreshing } finally { this.refreshing = undefined }\n  }\n\n  private async fetchRemote(): Promise<CatalogSnapshot> {\n    this.checkedAt = this.now()\n    try {\n      const response = await this.fetcher(this.remoteUrl, {\n        headers: { accept: 'application/json', 'user-agent': 'dsh-skin-market/remote-catalog' },\n        signal: AbortSignal.timeout(12_000),\n      })\n      if (!response.ok) throw new Error(`remote catalog returned HTTP ${response.status}`)\n      const remote = validateCatalog(await response.json())\n      const remoteTime = Date.parse(remote.generatedAt)\n      const currentTime = Date.parse(this.current.generatedAt)\n      if (remoteTime < currentTime) throw new Error('remote catalog is older than the accepted catalog')\n      if (remoteTime === currentTime && JSON.stringify(remote.skins) !== JSON.stringify(this.current.skins)) {\n        throw new Error('remote catalog changed without a new generatedAt timestamp')\n      }\n      this.current = remote\n      this.source = 'remote'\n      this.error = undefined\n      atomicWriteJson(cacheFile(this.profileDir), encodeCatalogWire(remote))\n    } catch (error) {\n      this.error = errorMessage(error)\n    }\n    return this.snapshot()\n  }\n}\n\nexport function repositorySlug(repo: string): string {\n  const match = /^https:\\/\\/github\\.com\\/([^/]+\\/[^/]+)\\/?$/.exec(repo)\n  if (match === null) throw new Error(`invalid GitHub repository: ${repo}`)\n  return match[1]\n}\n\nexport function recommend(current: SkinEntry, catalog: SkinEntry[], stars: ReadonlyMap<string, number>): string[] {\n  const score = (candidate: SkinEntry): number => {\n    const sharedTags = candidate.tags.filter(tag => current.tags.includes(tag)).length\n    const sharedModes = candidate.modes.filter(mode => current.modes.includes(mode)).length\n    const recent = Date.now() - Date.parse(candidate.releaseUpdatedAt) <= 30 * 86400000 ? 1 : 0\n    return sharedTags * 4 + sharedModes * 2 + Math.log1p(stars.get(candidate.id) ?? candidate.starsSnapshot) + recent - candidate.featuredRank / 100\n  }\n  // Score once per candidate. Recomputing inside sort makes the all-skin\n  // recommendation pass needlessly expensive as the scheduled catalog grows.\n  return catalog.filter(item => item.id !== current.id)\n    .map(item => ({ item, score: score(item) }))\n    .sort((a, b) => b.score - a.score)\n    .slice(0, 4)\n    .map(({ item }) => item.id)\n}\n\nexport async function catalogWithStars(_profileDir: string, catalog = loadCatalog()): Promise<CatalogSkin[]> {\n  const starMap = new Map(catalog.skins.map(skin => [skin.id, skin.starsSnapshot]))\n  return catalog.skins.map(skin => {\n    const localizedCopy = catalog.displayCopy?.skins[skin.id]\n    return {\n    ...skin,\n    ...(localizedCopy === undefined ? {} : { name: localizedSkinNameRecord(skin.name, localizedCopy), localizedCopy }),\n    githubStars: skin.starsSnapshot,\n    starsStale: false,\n    recommendations: recommend(skin, catalog.skins, starMap),\n    ...(catalog.heat?.[skin.id] === undefined ? {} : { heat: catalog.heat[skin.id] }),\n    }\n  })\n}\n"
